using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
using UnityEngine.Rendering.Universal;

namespace Snowglow.Editor {
 // Explicitly reconciles a manually arranged scene; never moves the facilities.
 public static class FacilityAccessAuthoring {
  const string Marker="Facility access | manual layout v1",Gate="Depot entry | north road",Request="Logs/FacilityAccess.request",Logs="Logs/FacilityAccess";
  static int checks;
  static T[] All<T>(Scene s)where T:Component=>s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<T>(true)).ToArray();
  static void Check(bool ok,string message){checks++;if(!ok)throw new InvalidOperationException("Facility access: "+message);}
  static Transform Entry(Scene s)=>All<Transform>(s).SingleOrDefault(t=>t.name==Marker)?.Find(Gate);
  public static bool Applied(Scene s)=>Entry(s);
  public static Vector3 DepotEntry(Scene s)=>Entry(s)?Entry(s).position:new Vector3(-95,0,-90);
  static string Pose(Transform t)=>t.localToWorldMatrix.ToString("R");
  static string Values(SnowSeed seed)=>JsonUtility.ToJson(new SnowVolumeGrid{depth=seed.grid.depth,credit=seed.grid.credit,initialVolume=seed.grid.initialVolume,disposed=seed.grid.disposed,revision=seed.grid.revision,blocked=new bool[0]});
  [InitializeOnLoadMethod]static void Register(){EditorApplication.update+=Pending;}
  static void Pending(){if(!File.Exists(Request)){EditorApplication.update-=Pending;return;}if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;EditorApplication.update-=Pending;File.Delete(Request);try{Apply();}catch(Exception e){Directory.CreateDirectory(Logs);File.WriteAllText(Logs+"/Validation.txt","FAIL: "+e);Debug.LogException(e);}}
  [MenuItem("Snowglow/Environment/Reconcile manual facility access")]
  public static void Apply(){
   Check(!EditorApplication.isPlayingOrWillChangePlaymode,"stop Play");var s=SceneManager.GetActiveScene();Check(s.path==SceneValidation.ScenePath,"open Pinefall");checks=0;Directory.CreateDirectory(Logs);SceneValidation.Validate(s);
   Check(EditorSceneManager.SaveScene(s,Logs+"/Pinefall-before-"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity",true),"backup");
   var placements=All<CatalogPlacement>(s).Where(p=>!string.IsNullOrEmpty(p.placementId)).ToArray();var poses=placements.ToDictionary(p=>p.placementId,p=>Pose(p.transform));var ids=placements.ToDictionary(p=>p.placementId,p=>p.assetId);var fleet=All<MachineController>(s).ToDictionary(m=>m.name,m=>Pose(m.transform));var roads=All<Transform>(s).Where(t=>t.name=="Road | asphalt").Select(Pose).ToArray();
   var snow=All<SnowField>(s).Single();string values=Values(snow.seed);var protectedPaths=All<Terrain>(s).Select(t=>AssetDatabase.GetAssetPath(t.terrainData)).Concat(snow.GetComponentsInChildren<MeshFilter>(true).Select(m=>AssetDatabase.GetAssetPath(m.sharedMesh))).Concat(new[]{AssetDatabase.GetAssetPath(snow.seed)}).Where(p=>!string.IsNullOrEmpty(p)).Distinct().ToDictionary(p=>p,p=>AssetDatabase.GetAssetDependencyHash(p));
   Views(s,"Before");Undo.IncrementCurrentGroup();int group=Undo.GetCurrentGroup();Undo.SetCurrentGroupName("Reconcile manually arranged facility access");bool saved=false;
   try{
    bool first=!Applied(s);if(first){var marker=new GameObject(Marker);SceneManager.MoveGameObjectToScene(marker,s);Undo.RegisterCreatedObjectUndo(marker,"Save manual facility access");var gate=new GameObject(Gate);gate.transform.SetParent(marker.transform,false);gate.transform.SetPositionAndRotation(new Vector3(-97.5f,SnowField.Ground,-70),Quaternion.Euler(0,180,0));var anchor=gate.AddComponent<AssetAnchor>();anchor.id="depot-entry";anchor.role=AnchorRole.RoadConnection;
     var sign=placements.Single(p=>p.placementId=="pinefall-sign-07");var face=sign.GetComponentsInChildren<AssetAnchor>(true).Single(a=>a.id=="label-face").transform;var local=sign.transform.InverseTransformDirection(-face.forward);var terrain=All<Terrain>(s).Single();var at=new Vector3(-107,0,-57.5f);at.y=terrain.SampleHeight(at)+terrain.transform.position.y-.015f;Undo.RecordObject(sign.transform,"Point depot sign to north entrance");sign.transform.SetPositionAndRotation(at,Quaternion.LookRotation(new Vector3(-Mathf.Sin(15*Mathf.Deg2Rad),0,-Mathf.Cos(15*Mathf.Deg2Rad)))*Quaternion.Inverse(Quaternion.LookRotation(local)));PrefabUtility.RecordPrefabInstancePropertyModifications(sign.transform);
     var reader=sign.transform.Find("Authoring | road reading position");Check(reader,"saved depot reader missing");Undo.RecordObject(reader,"Update depot road reading position");at=sign.transform.position-face.forward*7.5f;at.y=terrain.SampleHeight(at)+terrain.transform.position.y+1.8f;reader.position=at;
    }
    Physics.SyncTransforms();ValidateRoutes(s);IsometricLayoutAuthoring.ValidateLayout(s);int changed=Mask(snow);Check(values==Values(snow.seed),"snow quantities changed");SceneValidation.Validate(s);MechanicsChecks.Run();
    foreach(var p in placements)if(!first||p.placementId!="pinefall-sign-07")Check(poses[p.placementId]==Pose(p.transform),"placement moved "+p.placementId);
    Check(roads.SequenceEqual(All<Transform>(s).Where(t=>t.name=="Road | asphalt").Select(Pose)),"roads moved");foreach(var m in All<MachineController>(s))Check(fleet[m.name]==Pose(m.transform),"fleet moved");foreach(var h in protectedPaths)Check(h.Value==AssetDatabase.GetAssetDependencyHash(h.Key),"protected asset changed "+h.Key);
    var expected=placements.ToDictionary(p=>p.placementId,p=>Pose(p.transform));Views(s,"After");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);Check(EditorSceneManager.SaveScene(s),"save");saved=true;Undo.CollapseUndoOperations(group);s=EditorSceneManager.OpenScene(SceneValidation.ScenePath);Physics.SyncTransforms();ValidateRoutes(s);IsometricLayoutAuthoring.ValidateLayout(s);SceneValidation.Validate(s);MechanicsChecks.Run();Check(values==Values(All<SnowField>(s).Single().seed),"reopened snow changed");var reopened=All<CatalogPlacement>(s).Where(p=>!string.IsNullOrEmpty(p.placementId)).ToArray();Check(reopened.Length==ids.Count,"placement count changed");foreach(var p in reopened){Check(ids[p.placementId]==p.assetId,"identity changed");Check(expected[p.placementId]==Pose(p.transform),"reopened pose changed "+p.placementId);}foreach(var m in All<MachineController>(s))Check(fleet[m.name]==Pose(m.transform),"reopened fleet moved");foreach(var h in protectedPaths)Check(h.Value==AssetDatabase.GetAssetDependencyHash(h.Key),"original asset changed");
    File.WriteAllText(Logs+"/Validation.txt","PASS: Unity "+Application.unityVersion+" / "+EditorUserBuildSettings.activeBuildTarget+". "+checks+" assertions; saved/reopened Pinefall, scene validation and 19 snow checks passed.\nManual garage, fuel station and disposal yard poses preserved exactly. Depot north entry (-97.5, 5.13, -70); yard approach follows its existing Entrance anchor, retaining north-facing direction. Both 4.4 m-wide static sampled routes clear. Snow Depot sign points to north entry with saved road reader. No roads, other catalog poses or fleet moved. "+changed+" obstacle flags reconciled in separate seed revision; depth/credit/initial/disposed volume/revision, original seeds/meshes and terrain preserved. No district rebake or player-save writes. Before/after native views written. Physical driving/dumping/refuelling, Android packaging and Galaxy A07 performance remain untested.\n");Debug.Log(File.ReadAllText(Logs+"/Validation.txt"));
   }catch{if(!saved)Undo.RevertAllDownToGroup(group);throw;}
  }
  public static void ValidateRoutes(Scene s){
   Physics.SyncTransforms();var gate=Entry(s);Check(gate,"north depot entry missing");Check(Vector3.Dot(gate.forward,Vector3.back)>.99f,"depot entry must face into north edge");var at=gate.position;Corridor(new[]{at+Vector3.forward*5,at,at+Vector3.back*20},"north depot entry");var yard=All<CatalogPlacement>(s).Single(p=>p.placementId=="pinefall-disposal-yard");var entry=yard.GetComponentsInChildren<AssetAnchor>(true).Single(a=>a.id=="entrance").transform;Corridor(new[]{entry.position+entry.forward*8,entry.position,entry.position-entry.forward*8},"disposal entrance");
  }
  static void Corridor(Vector3[] path,string name){for(int i=1;i<path.Length;i++){var from=new Vector3(path[i-1].x,SnowField.Ground+2.7f,path[i-1].z);var to=new Vector3(path[i].x,SnowField.Ground+2.7f,path[i].z);Check(!Physics.OverlapSphere(from,2.2f,1<<0,QueryTriggerInteraction.Ignore).Any(c=>!c.GetComponentInParent<SnowField>()),name+" start occupied");var d=to-from;var hits=Physics.SphereCastAll(from,2.2f,d.normalized,d.magnitude,1<<0,QueryTriggerInteraction.Ignore).Where(h=>!h.collider.GetComponentInParent<SnowField>()).ToArray();Check(hits.Length==0,name+" blocked by "+string.Join(",",hits.Select(h=>h.collider.name)));}}
  static int Mask(SnowField snow){var mask=(bool[])snow.seed.grid.blocked.Clone();int changed=0;for(int i=0;i<mask.Length;i++){bool v=Physics.CheckBox(new Vector3(snow.seed.grid.X(i),SnowField.Ground+.85f,snow.seed.grid.Z(i)),new Vector3(SnowVolumeGrid.Cell*.45f,.65f,SnowVolumeGrid.Cell*.45f),Quaternion.identity,1<<0,QueryTriggerInteraction.Ignore);if(v!=mask[i]){mask[i]=v;changed++;}}if(changed>0){var copy=UnityEngine.Object.Instantiate(snow.seed);copy.name="Pinefall | manual facility access obstacles";copy.grid.blocked=mask;AssetDatabase.CreateAsset(copy,AssetDatabase.GenerateUniqueAssetPath(CatalogPreparation.Root+"/SceneData/ManualFacilitySnowObstacles.asset"));Undo.RecordObject(snow,"Bind manual facility obstacle mask");snow.seed=copy;EditorUtility.SetDirty(snow);}return changed;}
  public static void Views(Scene s,string phase,string folder=Logs){var source=All<CameraRig>(s).Single();var go=new GameObject("Temporary facility access review"){hideFlags=HideFlags.HideAndDontSave};try{var c=go.AddComponent<Camera>();c.CopyFrom(source.view);c.enabled=false;c.nearClipPlane=.1f;c.farClipPlane=1000;c.aspect=16f/9;go.AddComponent<UniversalAdditionalCameraData>().renderPostProcessing=false;foreach(var id in new[]{"pinefall-garage","pinefall-disposal-yard"}){var p=All<CatalogPlacement>(s).Single(x=>x.placementId==id);var center=id=="pinefall-garage"?new Vector3(-95,SnowField.Ground,-85):p.transform.position;foreach(bool top in new[]{false,true}){c.orthographic=true;c.orthographicSize=top?31:29;c.transform.position=center+(top?new Vector3(0,100,.01f):new Vector3(-50,65,65));c.transform.LookAt(center);var rt=new RenderTexture(1280,720,24);var active=RenderTexture.active;Texture2D image=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;image=new Texture2D(1280,720,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1280,720),0,0);image.Apply();File.WriteAllBytes(folder+"/"+phase+"-"+id+(top?"-top":"-entry")+".png",image.EncodeToPNG());}finally{c.targetTexture=null;RenderTexture.active=active;rt.Release();UnityEngine.Object.DestroyImmediate(rt);if(image)UnityEngine.Object.DestroyImmediate(image);}}}}finally{UnityEngine.Object.DestroyImmediate(go);}}
 }
}
